const items = $input.all();

const cleanedItems = items.map(item => {
  const data = item.json;

  const stripHtml = (html) => {
    if (!html) return '';
    return html
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<p[^>]*>/gi, '')
      .replace(/<\/p>/gi, '\n')
      .replace(/<li[^>]*>/gi, '• ')
      .replace(/<\/li>/gi, '\n')
      .replace(/<[^>]+>/g, '')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&nbsp;/g, ' ')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  };

  const extractImageUrl = (html) => {
    if (!html) return '';
    const match = html.match(/<img[^>]+src=["']([^"']+)["']/i);
    return match ? match[1] : '';
  };

  const extractPrice = (html) => {
    if (!html) return { amount: '', currency: '' };
    const match = html.match(/<p class="price">([\d.,]+)\s*([A-Z]+)<\/p>/i);
    if (!match) return { amount: '', currency: '' };
    return {
      amount: parseFloat(match[1].replace(',', '.')),
      currency: match[2],
    };
  };

  const extractDescription = (html) => {
    if (!html) return '';
    let cleaned = html.replace(/<p class="image">.*?<\/p>/is, '');
    cleaned = cleaned.replace(/<p class="price">.*?<\/p>/is, '');
    cleaned = stripHtml(cleaned);

    const cutoffPhrases = [
      'Instant digital download',
      'Please note',
      'What’s included',
      "What's included",
      'How it works',
      'This is a digital download',
      'No physical item will be shipped',
    ];

    for (const phrase of cutoffPhrases) {
      const idx = cleaned.toLowerCase().indexOf(phrase.toLowerCase());
      if (idx !== -1) {
        cleaned = cleaned.slice(0, idx).trim();
        break;
      }
    }

    return cleaned.slice(0, 500).trim();
  };

  const extractShopFromTitle = (title) => {
    if (!title) return '';
    const match = title.match(/\bby\s+([A-Z][A-Za-z0-9]+)$/);
    return match ? match[1] : '';
  };

  const cleanTitle = (title) => {
    if (!title) return '';
    return title.replace(/\s*by\s+[A-Z][A-Za-z0-9]+$/, '').trim();
  };

  const extractListingId = (url) => {
    if (!url) return '';
    const match = url.match(/\/listing\/(\d+)\//);
    return match ? match[1] : '';
  };

  const makeSlugId = (title) => {
    if (!title) return '';
    return title.toLowerCase().trim().replace(/\s+/g, '-');
  };

  const rawContent = data.content || '';
  const rawTitle = data.title || '';
  const title = cleanTitle(rawTitle);
  const price = extractPrice(rawContent);
  const cleanDescription = extractDescription(rawContent);
  const etsyUrl = data.link || '';
  const imageUrl = extractImageUrl(rawContent);
  const now = new Date().toISOString();
  const listingId = extractListingId(etsyUrl) || makeSlugId(title);

  return {
    json: {
      TITLE: title,
      DESCRIPTION: cleanDescription,
      CLEAN_DESCRIPTION: cleanDescription,
      PRICE: price.amount ?? '',
      CURRENCY_CODE: price.currency || '',
      QUANTITY: '',
      TAGS: '',
      MATERIALS: '',
      IMAGE1: imageUrl,
      IMAGE2: '',
      IMAGE3: '',
      IMAGE4: '',
      IMAGE5: '',
      IMAGE6: '',
      IMAGE7: '',
      IMAGE8: '',
      IMAGE9: '',
      IMAGE10: '',
      'VARIATION 1 TYPE': '',
      'VARIATION 1 NAME': '',
      'VARIATION 1 VALUES': '',
      'VARIATION 2 TYPE': '',
      'VARIATION 2 NAME': '',
      'VARIATION 2 VALUES': '',
      SKU: '',
      LISTING_ID: listingId,
      ETSY_URL: etsyUrl,
      SHOP_NAME: extractShopFromTitle(rawTitle) || 'PLACEHOLDER_ETSY_SHOP_NAME',
      MAIN_IMAGE: imageUrl,
      PIN_SOURCE_IMAGE: imageUrl,
      BOARD: 'DARK MOODY WALL ART',
      STATUS: 'new',
      IMAGE_PROMPT: '',
      PIN_IMAGE_URL: '',
      PIN_TITLE: '',
      PIN_DESCRIPTION: '',
      PIN_HASHTAGS: '',
      PIN_ALT_TEXT: '',
      PIN_POST_DATE: '',
      PIN_ATTEMPTS: 0,
      LAST_ERROR: '',
      CONTENT_GENERATED: 'FALSE',
      IMAGE_GENERATED: 'FALSE',
      POSTED_TO_PINTEREST: 'FALSE',
      RSS_IMPORTED: 'TRUE',
      CREATED_AT: now,
      UPDATED_AT: now,
    }
  };
});

return cleanedItems;

const items = $input.all();

return items.map(item => {
  const row = item.json;

  const isEmpty = (v) => v === undefined || v === null || String(v).trim() === '';

  const attempts = Number(row.PIN_ATTEMPTS || 0);
  const isAlreadyPosted = String(row.POSTED_TO_PINTEREST || '').toUpperCase() === 'TRUE';
  const canRetry = attempts < 5;

  const needsImagePrompt = isEmpty(row.IMAGE_PROMPT);
  const needsSeo = isEmpty(row.PIN_TITLE) || isEmpty(row.PIN_DESCRIPTION);
  const needsImageGeneration = isEmpty(row.PIN_IMAGE_URL);

  const readyToPost = !needsImagePrompt && !needsSeo && !needsImageGeneration && !isAlreadyPosted && canRetry;
  const shouldProcess = !isAlreadyPosted && canRetry;

  return {
    json: {
      ...row,
      PIN_ATTEMPTS: attempts,
      needs_image_prompt: needsImagePrompt,
      needs_seo: needsSeo,
      needs_image_generation: needsImageGeneration,
      is_already_posted: isAlreadyPosted,
      can_retry: canRetry,
      ready_to_post: readyToPost,
      should_process: shouldProcess,
    }
  };
});

const input = $input.first().json;

// The Google Suggest response is inside input.data as a string
let data = input.data ?? input;

// Parse if it's a string
if (typeof data === 'string') {
  data = JSON.parse(data);
}

const seed = Array.isArray(data) ? data[0] : '';
const suggestions = Array.isArray(data) && Array.isArray(data[1]) ? data[1] : [];

const keywords = [...new Set(suggestions.filter(k => k && k !== seed))].slice(0, 3);

return [
  {
    json: {
      seed,
      top_keywords: keywords
    }
  }
];
